const fs = require('fs');

// ------------------------------------------------------------
// Configuration & constants
// ------------------------------------------------------------
const LEPRECHAUN_RICHES = { min: 0.93, media: 3.59, max: 7.91, chance: 38 };

// Paths to external JSON files
