    }
    const stats = updateStats(jogoData);
    return `🍀 *PORCENTAGENS E ESTATÍSTICAS* 💰\n\n*❲${game}❳*\n• *Mínimo:* R$ ${stats.min.toFixed(2)}\n• *Média:* R$ ${stats.media.toFixed(2)}\n• *Máximo:* R$ ${stats.max.toFixed(2)}\n• *Chance:* ${stats.chance}%\n\nObservação: As porcentagens podem conter alguma divergência...`;
}

